const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define location and time
  const prescott = ee.Geometry.Point([-112.4685, 34.5400]); // Prescott, Arizona
  const startDate = '2017-06-01';
  const endDate = '2017-06-30';

  console.log('Analyzing temperatures in Prescott, Arizona for June 2017...');

  // 2. Load MODIS LST data (Terra satellite)
  let collection = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterBounds(prescott)
    .filterDate(startDate, endDate)
    .select(['LST_Day_1km', 'LST_Night_1km']);

  const collectionSize = collection.size().getInfo();
  console.log(`Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No MODIS data found. Trying Aqua satellite...');
    collection = ee.ImageCollection('MODIS/006/MYD11A1')
      .filterBounds(prescott)
      .filterDate(startDate, endDate)
      .select(['LST_Day_1km', 'LST_Night_1km']);

    const aquaSize = collection.size().getInfo();
    console.log(`Aqua images found: ${aquaSize}`);

    if (aquaSize === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Convert Kelvin to Fahrenheit and find maximum temperature
  const lstToFahrenheit = function(img) {
    const dayF = img.select('LST_Day_1km').multiply(0.02).subtract(273.15).multiply(9/5).add(32);
    const nightF = img.select('LST_Night_1km').multiply(0.02).subtract(273.15).multiply(9/5).add(32);
    return img.addBands(dayF.rename('Day_F')).addBands(nightF.rename('Night_F'));
  };

  const collectionF = collection.map(lstToFahrenheit);

  // 4. Get statistics
  const stats = collectionF.select(['Day_F', 'Night_F']).reduce(ee.Reducer.max())
    .reduceRegion({
      reducer: ee.Reducer.max(),
      geometry: prescott,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

  const maxDayTemp = stats['Day_F_max'];
  const maxNightTemp = stats['Night_F_max'];

  console.log(`Max Day Temperature: ${maxDayTemp ? maxDayTemp.toFixed(1) : 'null'}°F`);
  console.log(`Max Night Temperature: ${maxNightTemp ? maxNightTemp.toFixed(1) : 'null'}°F`);

  // 5. Validation and answer
  if (maxDayTemp === null || maxDayTemp === undefined) {
    console.log('<answer>C3</answer>');
    return;
  }

  if (maxDayTemp < -50 || maxDayTemp > 150) {
    console.log('Temperature out of valid range');
    console.log('<answer>C3</answer>');
    return;
  }

  const maxTemp = Math.max(maxDayTemp, maxNightTemp || 0);
  console.log(`Overall Max Temperature: ${maxTemp.toFixed(1)}°F`);

  if (maxTemp >= 100) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
